package data_generation

import (
	"os"
	"path/filepath"
	"testing"
)

// PoB's data files come in two shapes: the chunk fills the table itself, or
// (since PoB's class syntax rework) it returns a function that does.
func TestExecuteScriptAsFuncReadsBothPoBFileShapes(t *testing.T) {
	scripts := map[string]string{
		"chunk fills table": `local itemBases = ...
itemBases["Driftwood Wand"] = { type = "Wand" }
itemBases["Goat's Horn"] = { type = "Wand" }
`,
		"chunk returns function": `-- This file is automatically generated, do not edit!
return function(itemBases)
itemBases["Driftwood Wand"] = { type = "Wand" }
itemBases["Goat's Horn"] = { type = "Wand" }
end
`,
	}
	for name, script := range scripts {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "wand.lua")
			if err := os.WriteFile(path, []byte(script), 0o644); err != nil {
				t.Fatal(err)
			}
			table, err := NewLuaExecutor().ExecuteScriptAsFunc(path)
			if err != nil {
				t.Fatal(err)
			}
			if got := len(mapItemBasesFromLua(table)); got != 2 {
				t.Fatalf("read %d item bases, want 2", got)
			}
		})
	}
}
